import SwiftData
import Testing

@Test("salva nota e recarrega via Query")
func persistencia() throws {
    let cfg = ModelConfiguration(isStoredInMemoryOnly: true)
    let container = try ModelContainer(for: Note.self, configurations: cfg)
    let ctx = container.mainContext

    ctx.insert(Note(title: "A", detail: "a"))
    try ctx.save()

    let all = try ctx.fetch(FetchDescriptor<Note>())
    #expect(all.count == 1)
    #expect(all[0].title == "A")
}

// Stub de URLSession via URLProtocol
final class StubURLProtocol: URLProtocol {
    nonisolated(unsafe) static var handler: ((URLRequest) -> (HTTPURLResponse, Data))?
    override class func canInit(with req: URLRequest) -> Bool { true }
    override class func canonicalRequest(for r: URLRequest) -> URLRequest { r }
    override func startLoading() {
        guard let (resp, data) = Self.handler?(request) else { return }
        client?.urlProtocol(self, didReceive: resp, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: data)
        client?.urlProtocolDidFinishLoading(self)
    }
    override func stopLoading() {}
}

import XCTest

final class LoginUITests: XCTestCase {
    override func setUpWithError() throws {
        continueAfterFailure = false
    }

    func test_login_fluxoFeliz() {
        let app = XCUIApplication()
        app.launchArguments += ["-UITestFakeAPI", "1"]
        app.launch()

        app.textFields["email"].tap()
        app.textFields["email"].typeText("fernando@exemplo.com")

        app.secureTextFields["senha"].tap()
        app.secureTextFields["senha"].typeText("segredo123")

        app.buttons["Entrar"].tap()

        XCTAssertTrue(app.staticTexts["Ola, Fernando"].waitForExistence(timeout: 5))
    }
}

import SnapshotTesting
import SwiftUI
import XCTest

final class ProductCardSnapshotTests: XCTestCase {
    func test_card_dark() {
        let view = ProductCard(product: .sample).preferredColorScheme(.dark)
        assertSnapshot(of: view, as: .image(layout: .device(config: .iPhone13)))
    }

    func test_card_dynamicTypeXL() {
        let view = ProductCard(product: .sample)
            .environment(\.sizeCategory, .accessibilityExtraLarge)
        assertSnapshot(of: view, as: .image(layout: .device(config: .iPhone13)))
    }
}
